import json

from django.db import migrations


def editorjs_to_html(content):
    """Editor.js JSON 블록을 HTML로 변환."""
    if not content:
        return ""
    if isinstance(content, str):
        try:
            content = json.loads(content)
        except (json.JSONDecodeError, ValueError):
            return content  # 이미 HTML이거나 일반 텍스트

    if not isinstance(content, dict) or "blocks" not in content:
        return str(content)

    parts = []
    for block in content["blocks"]:
        btype = block.get("type", "")
        data = block.get("data", {})

        if btype == "paragraph":
            parts.append(f"<p>{data.get('text', '')}</p>")
        elif btype == "header":
            level = data.get("level", 2)
            parts.append(f"<h{level}>{data.get('text', '')}</h{level}>")
        elif btype == "list":
            style = data.get("style", "unordered")
            tag = "ol" if style == "ordered" else "ul"
            items = "".join(f"<li>{item}</li>" for item in data.get("items", []))
            parts.append(f"<{tag}>{items}</{tag}>")
        elif btype == "image":
            url = data.get("file", {}).get("url", "")
            caption = data.get("caption", "")
            parts.append(f'<img src="{url}" alt="{caption}">')
        elif btype == "quote":
            text = data.get("text", "")
            parts.append(f"<blockquote>{text}</blockquote>")
        elif btype == "code":
            code = data.get("code", "")
            parts.append(f"<pre><code>{code}</code></pre>")
        elif btype == "delimiter":
            parts.append("<hr>")
        else:
            text = data.get("text", "")
            if text:
                parts.append(f"<p>{text}</p>")

    return "\n".join(parts)


def convert_forward(apps, schema_editor):
    Episode = apps.get_model("stories", "Episode")
    for episode in Episode.objects.all():
        if episode.content:
            episode.content = editorjs_to_html(episode.content)
            episode.save(update_fields=["content"])


